import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getFarmerSessionFromRequest } from '@/lib/farmer-session'
import { refundPayment } from '@/lib/razorpay'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

// Farmer declines a pending order. This runs server-side (not in the
// dashboard) because issuing a real refund needs the Razorpay secret. Steps:
//   1. authorise the farmer and confirm the order is theirs and still pending
//   2. return the reserved stock
//   3. if the buyer paid by Razorpay, issue a real partial refund for this
//      line's amount and record it; other paid methods get a manual
//      'initiated' marker as before
//   4. mark the order declined
export async function POST(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const session = getFarmerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Please log in.' }, { status: 401 })

  const { id } = await ctx.params
  if (!id || !UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })

  const body = await req.json().catch(() => null)
  const reason = String((body as { reason?: unknown } | null)?.reason ?? '').trim().slice(0, 300)

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: order, error: loadErr } = await supabase
    .from('orders')
    .select('id, farmer_id, status, quantity, total_price, produce_listing_id, payment_method, payment_status, razorpay_payment_id, order_code')
    .eq('id', id)
    .maybeSingle()

  if (loadErr) return NextResponse.json({ error: loadErr.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.farmer_id !== session.farmerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }
  // Only a pending order can be declined. This also makes the call idempotent:
  // a double-tap finds the order already declined and refunds nothing twice.
  if (order.status !== 'pending') {
    return NextResponse.json({ error: 'This order can no longer be declined.' }, { status: 409 })
  }

  // 1. Return the reserved stock.
  if (order.produce_listing_id && order.quantity != null && order.quantity > 0) {
    try {
      await supabase.rpc('increment_stock', {
        p_listing_id: order.produce_listing_id,
        p_qty: order.quantity,
      })
    } catch (e) {
      console.error('[YFF] restock on decline failed:', e)
    }
  }

  // 2. Refund if the buyer actually paid.
  const update: Record<string, unknown> = { status: 'declined', decline_reason: reason || null }

  const paidByRazorpay = order.payment_status === 'paid' && !!order.razorpay_payment_id
  const paidByOther =
    order.payment_status === 'completed' ||
    order.payment_status === 'payment_claimed' ||
    order.payment_status === 'pending_confirmation'

  if (paidByRazorpay) {
    const amountPaise = Math.round((Number(order.total_price) || 0) * 100)
    if (amountPaise > 0) {
      try {
        const refund = await refundPayment({
          paymentId: order.razorpay_payment_id as string,
          amountPaise,
          notes: { order_code: order.order_code ?? '', order_id: order.id },
        })
        update.refund_id = refund.id
        update.refund_status = refund.status ?? 'processed'
        update.refund_amount = Math.round(refund.amountPaise / 100)
        update.refunded_at = new Date().toISOString()
      } catch (e) {
        // Refund failed at Razorpay. Don't silently swallow it — keep the
        // order pending so the farmer can retry, and surface the error.
        console.error('[YFF] razorpay refund failed:', e)
        return NextResponse.json(
          { error: 'Could not issue the refund. The order was not declined — please try again.' },
          { status: 502 },
        )
      }
    }
  } else if (paidByOther) {
    // Non-Razorpay paid (UPI/manual): flag for manual refund as before.
    update.refund_status = 'initiated'
  }

  const { error: updErr } = await supabase.from('orders').update(update).eq('id', id)
  if (updErr) {
    console.error('[YFF] decline update failed:', updErr.message)
    return NextResponse.json({ error: 'Could not decline the order. Please try again.' }, { status: 500 })
  }

  return NextResponse.json({
    ok: true,
    refunded: !!update.refund_id,
    refundStatus: (update.refund_status as string | undefined) ?? null,
  })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { hashPassword, verifyPassword } from '@/lib/password'
import { getFarmerSessionFromRequest } from '@/lib/farmer-session'
import { rateLimit } from '@/lib/rate-limit'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function POST(req: NextRequest) {
  // The previous version trusted a body-supplied farmerId — that let anyone
  // who guessed/scraped a farmer UUID change their password. Now we read the
  // farmerId from the auth cookie only.
  const session = getFarmerSessionFromRequest(req)
  if (!session) {
    return NextResponse.json({ error: 'Please log in first.' }, { status: 401 })
  }

  const ip = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown'
  if (
    !rateLimit(`reset-pw:farmer:${session.farmerId}`, 5, 60 * 60 * 1000) ||
    !rateLimit(`reset-pw:ip:${ip}`, 15, 60 * 60 * 1000)
  ) {
    return NextResponse.json({ error: 'Too many attempts. Try again later.' }, { status: 429 })
  }

  const body = await req.json().catch(() => ({}))
  const currentPassword: string = String((body as { currentPassword?: unknown }).currentPassword ?? '')
  const newPassword: string = String((body as { newPassword?: unknown }).newPassword ?? '').trim()

  if (!currentPassword) {
    return NextResponse.json({ error: 'Current password is required.' }, { status: 400 })
  }
  if (newPassword.length < 6) {
    return NextResponse.json({ error: 'Password must be at least 6 characters.' }, { status: 400 })
  }
  if (newPassword.length > 128) {
    return NextResponse.json({ error: 'Password is too long.' }, { status: 400 })
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  // Verify the current password against the stored hash before allowing
  // an update. Without this, anyone with a live session could change the
  // password without knowing the existing one.
  const { data: farmer } = await supabase
    .from('farmers')
    .select('password_hash')
    .eq('id', session.farmerId)
    .maybeSingle()

  if (!farmer?.password_hash || !verifyPassword(currentPassword, farmer.password_hash)) {
    return NextResponse.json({ error: 'Current password is incorrect' }, { status: 400 })
  }

  const { error } = await supabase
    .from('farmers')
    .update({ password_hash: hashPassword(newPassword) })
    .eq('id', session.farmerId)

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })
  return NextResponse.json({ ok: true })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { isModeratorRequest, getModeratorZone } from '@/lib/moderator-session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function GET(req: NextRequest) {
  if (!isModeratorRequest(req)) {
    return NextResponse.json({ error: 'Moderator login required.' }, { status: 401 })
  }

  const zone = getModeratorZone()
  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  // All farmers in this zone — needed to scope orders/listings to the zone.
  const { data: zoneFarmers, error: fErr } = await supabase
    .from('farmers')
    .select('id, active')
    .eq('region_slug', zone)

  if (fErr) {
    console.error('[YFF moderator/stats] farmers query failed:', fErr.message)
    return NextResponse.json({ error: fErr.message }, { status: 500 })
  }

  const farmerIds = (zoneFarmers ?? []).map((f) => f.id)
  const activeFarmers = (zoneFarmers ?? []).filter((f) => f.active).length

  const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString()

  // Default everything that depends on having farmers in the zone.
  let ordersThisWeek = 0
  let gmvThisWeek = 0
  let consumers = 0
  let pendingApprovals = 0

  if (farmerIds.length > 0) {
    // Orders this week (count) + GMV this week (sum of total_price).
    const { data: weekOrders } = await supabase
      .from('orders')
      .select('total_price')
      .in('farmer_id', farmerIds)
      .gte('created_at', weekAgo)
    ordersThisWeek = weekOrders?.length ?? 0
    gmvThisWeek = (weekOrders ?? []).reduce((sum, o) => sum + Number(o.total_price ?? 0), 0)

    // Consumers = distinct buyers who have ever ordered from a zone farmer.
    const { data: buyerRows } = await supabase
      .from('orders')
      .select('consumer_id')
      .in('farmer_id', farmerIds)
      .not('consumer_id', 'is', null)
    consumers = new Set((buyerRows ?? []).map((r) => r.consumer_id)).size

    // Pending approvals: listings awaiting review. The listing-approval flow
    // (Feature 3) is not built yet, so this is 0 until a 'pending_review'
    // status exists — counting it here keeps the card correct once it ships.
    const { count: pendingCount } = await supabase
      .from('produce_listings')
      .select('id', { count: 'exact', head: true })
      .in('farmer_id', farmerIds)
      .eq('status', 'pending_review')
    pendingApprovals = pendingCount ?? 0
  }

  // Open escalations: anything not yet resolved, in this zone (Feature 7).
  const { count: openCount } = await supabase
    .from('escalations')
    .select('id', { count: 'exact', head: true })
    .eq('region_slug', zone)
    .neq('status', 'resolved')
  const openEscalations = openCount ?? 0

  return NextResponse.json({
    zone,
    stats: {
      activeFarmers,
      consumers,
      ordersThisWeek,
      gmvThisWeek,
      openEscalations,
      pendingApprovals,
    },
  })
}

'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import ModeratorShell, { useModeratorAuth } from './ModeratorShell'

type Stats = {
  activeFarmers: number
  consumers: number
  ordersThisWeek: number
  gmvThisWeek: number
  openEscalations: number
  pendingApprovals: number
}

export default function ModeratorDashboard() {
  const router = useRouter()
  const { zone, checked } = useModeratorAuth()
  const [stats, setStats] = useState<Stats | null>(null)
  const [error, setError] = useState('')

  useEffect(() => {
    if (!checked) return
    fetch('/api/moderator/stats', { credentials: 'same-origin' })
      .then((r) => r.json())
      .then((json) => {
        if (json?.stats) setStats(json.stats)
        else setError(json?.error ?? 'Could not load stats.')
      })
      .catch(() => setError('Network error.'))
  }, [checked])

  if (!checked || !zone) {
    return (
      <main className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="w-10 h-10 border-4 border-green-700 border-t-transparent rounded-full animate-spin" />
      </main>
    )
  }

  const today = new Date().toLocaleDateString('en-IN', {
    weekday: 'long', day: 'numeric', month: 'long', year: 'numeric',
  })

  const hasAlerts = (stats?.openEscalations ?? 0) > 0 || (stats?.pendingApprovals ?? 0) > 0

  return (
    <ModeratorShell title="Dashboard" subtitle={today} zone={zone}>
      {/* Alert strip */}
      {stats && (
        hasAlerts ? (
          <div className="bg-amber-50 border border-amber-200 text-amber-800 rounded-xl px-4 py-3 text-sm font-semibold mb-5">
            ⚠ {stats.pendingApprovals > 0 && `${stats.pendingApprovals} listing${stats.pendingApprovals > 1 ? 's' : ''} pending approval`}
            {stats.pendingApprovals > 0 && stats.openEscalations > 0 && ' · '}
            {stats.openEscalations > 0 && `${stats.openEscalations} open escalation${stats.openEscalations > 1 ? 's' : ''} need attention`}
          </div>
        ) : (
          <div className="bg-green-50 border border-green-200 text-green-800 rounded-xl px-4 py-3 text-sm font-semibold mb-5">
            ✓ All clear — no pending approvals or open escalations
          </div>
        )
      )}

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 rounded-xl px-4 py-3 text-sm font-semibold mb-5">{error}</div>
      )}

      {/* Stat cards */}
      <div className="grid grid-cols-2 lg:grid-cols-3 gap-3 md:gap-4">
        <StatCard label="Active farmers" value={stats?.activeFarmers} />
        <StatCard label="Consumers" value={stats?.consumers} />
        <StatCard label="Orders this week" value={stats?.ordersThisWeek} />
        <StatCard label="GMV this week" value={stats ? `₹${stats.gmvThisWeek.toLocaleString('en-IN')}` : undefined} />
        <StatCard label="Open escalations" value={stats?.openEscalations} tone={(stats?.openEscalations ?? 0) > 0 ? 'red' : undefined} />
        <StatCard label="Pending approvals" value={stats?.pendingApprovals} tone={(stats?.pendingApprovals ?? 0) > 0 ? 'amber' : undefined} />
      </div>

      {/* Quick actions */}
      <div className="mt-7">
        <p className="text-[11px] font-bold text-gray-400 uppercase tracking-wide mb-2">Quick actions</p>
        <div className="flex flex-wrap gap-2">
          <button
            onClick={() => router.push('/moderator/farmers/new')}
            className="bg-green-800 text-white text-sm font-bold px-4 py-2.5 rounded-xl active:bg-green-900"
          >
            + Onboard a farmer
          </button>
          <button
            onClick={() => router.push('/moderator/listings')}
            className="bg-white border border-gray-200 text-gray-700 text-sm font-bold px-4 py-2.5 rounded-xl active:bg-gray-50"
          >
            Review listings
          </button>
          <button
            onClick={() => router.push('/moderator/escalations')}
            className="bg-white border border-gray-200 text-gray-700 text-sm font-bold px-4 py-2.5 rounded-xl active:bg-gray-50"
          >
            View escalations
          </button>
          <button
            onClick={() => router.push('/moderator/reports')}
            className="bg-white border border-gray-200 text-gray-700 text-sm font-bold px-4 py-2.5 rounded-xl active:bg-gray-50"
          >
            View reports
          </button>
        </div>
      </div>
    </ModeratorShell>
  )
}

function StatCard({
  label, value, tone, hint,
}: { label: string; value?: number | string; tone?: 'red' | 'amber'; hint?: string }) {
  const valueColor = tone === 'red' ? 'text-red-600' : tone === 'amber' ? 'text-amber-600' : 'text-gray-900'
  return (
    <div className="bg-white rounded-2xl border border-gray-100 p-4 shadow-sm">
      <p className={`text-2xl md:text-3xl font-extrabold ${valueColor}`}>
        {value === undefined ? '—' : value}
      </p>
      <p className="text-xs text-gray-500 mt-1 font-medium">{label}</p>
      {hint && <p className="text-[10px] text-gray-300 mt-0.5">{hint}</p>}
    </div>
  )
}

'use client'

import { useRouter, usePathname } from 'next/navigation'
import { useEffect, useState, type ReactNode } from 'react'

type NavItem = { label: string; href: string; ready: boolean }

// The 9 sections from the spec. Only the ones built so far route anywhere;
// the rest are shown greyed with a "soon" tag so the full shape is visible.
const NAV: NavItem[] = [
  { label: 'Dashboard', href: '/moderator', ready: true },
  { label: 'Farmer onboarding', href: '/moderator/farmers', ready: true },
  { label: 'Listings', href: '/moderator/listings', ready: true },
  { label: 'Supply & demand', href: '/moderator/supply', ready: true },
  { label: 'Consumers', href: '/moderator/consumers', ready: true },
  { label: 'Delivery agents', href: '/moderator/agents', ready: true },
  { label: 'Escalations', href: '/moderator/escalations', ready: true },
  { label: 'Price management', href: '/moderator/prices', ready: true },
  { label: 'Reports', href: '/moderator/reports', ready: true },
]

export default function ModeratorShell({
  title,
  subtitle,
  zone,
  children,
}: {
  title: string
  subtitle?: string
  zone: string
  children: ReactNode
}) {
  const router = useRouter()
  const pathname = usePathname()
  const [menuOpen, setMenuOpen] = useState(false)

  const logout = async () => {
    await fetch('/api/moderator/logout', { method: 'POST', credentials: 'same-origin' }).catch(() => null)
    router.replace('/moderator/login')
  }

  const zoneLabel = zone.charAt(0).toUpperCase() + zone.slice(1)

  return (
    <div className="min-h-screen bg-gray-50 flex">
      {/* Sidebar */}
      <aside
        className={`fixed md:static z-30 inset-y-0 left-0 w-60 bg-green-950 text-green-50 flex-col transition-transform ${
          menuOpen ? 'flex translate-x-0' : 'hidden md:flex md:translate-x-0'
        }`}
      >
        <div className="px-5 pt-6 pb-5 border-b border-green-900/60">
          <p className="text-lg font-extrabold tracking-tight text-white">GoGrameen</p>
          <p className="text-[11px] text-green-300/80">Moderator · {zoneLabel}</p>
        </div>
        <nav className="flex-1 py-3">
          {NAV.map((item) => {
            const active = pathname === item.href
            if (!item.ready) {
              return (
                <div
                  key={item.href}
                  className="flex items-center justify-between px-5 py-2.5 text-sm text-green-300/40 cursor-not-allowed"
                >
                  <span>{item.label}</span>
                  <span className="text-[9px] uppercase bg-green-900/50 px-1.5 py-0.5 rounded">soon</span>
                </div>
              )
            }
            return (
              <button
                key={item.href}
                onClick={() => { setMenuOpen(false); router.push(item.href) }}
                className={`w-full text-left px-5 py-2.5 text-sm transition-colors ${
                  active ? 'bg-green-800 text-white font-semibold border-l-4 border-green-300' : 'text-green-100 hover:bg-green-900/60'
                }`}
              >
                {item.label}
              </button>
            )
          })}
        </nav>
        <button onClick={logout} className="px-5 py-4 text-xs text-green-300 hover:text-white text-left border-t border-green-900/60">
          Log out
        </button>
      </aside>

      {menuOpen && (
        <div className="fixed inset-0 bg-black/40 z-20 md:hidden" onClick={() => setMenuOpen(false)} />
      )}

      {/* Main */}
      <div className="flex-1 min-w-0">
        <header className="bg-white border-b border-gray-100 px-4 md:px-8 py-4 flex items-center justify-between gap-3">
          <div className="flex items-center gap-3 min-w-0">
            <button onClick={() => setMenuOpen(true)} className="md:hidden text-gray-700 text-xl leading-none">☰</button>
            <div className="min-w-0">
              <h1 className="text-lg md:text-xl font-extrabold text-gray-900 leading-tight truncate">{title}</h1>
              {subtitle && <p className="text-xs text-gray-500 truncate">{subtitle}</p>}
            </div>
          </div>
          <span className="text-[11px] font-semibold bg-green-100 text-green-800 px-3 py-1 rounded-full whitespace-nowrap">
            {zoneLabel} zone
          </span>
        </header>
        <main className="p-4 md:p-8 max-w-5xl">{children}</main>
      </div>
    </div>
  )
}

// Shared client-side auth guard. Returns the zone once confirmed, or redirects
// to /moderator/login. Every moderator page uses this so a farmer / consumer /
// rider who lands on a /moderator URL is bounced out immediately.
export function useModeratorAuth() {
  const router = useRouter()
  const [zone, setZone] = useState<string | null>(null)
  const [checked, setChecked] = useState(false)

  useEffect(() => {
    let cancelled = false
    fetch('/api/moderator/me', { credentials: 'same-origin' })
      .then((r) => r.json())
      .then((json) => {
        if (cancelled) return
        if (json?.moderator) { setZone(json.zone); setChecked(true) }
        else router.replace('/moderator/login')
      })
      .catch(() => { if (!cancelled) router.replace('/moderator/login') })
    return () => { cancelled = true }
  }, [router])

  return { zone, checked }
}

-- ================================================================
-- YFF — Order audit trail (order_events)
-- Run in: Supabase Dashboard → SQL Editor → New Query → Run
-- Safe to re-run. Backfill runs only once (when order_events is empty).
--
-- Adds an append-only history of every order change. A trigger on
-- `orders` writes one row per changed status field, so the log captures
-- changes even when a row is edited directly in the Supabase dashboard.
--
-- "Who did it": app writes go through the service role, so the DB can't
-- tell a farmer from a rider on its own. API routes pass the real actor
-- by running `SET LOCAL app.actor_type = '...'` (and optionally
-- `app.actor_id`) in the same transaction as the UPDATE; the trigger
-- reads those. When unset (e.g. a dashboard edit), actor_type = 'system'.
-- ================================================================

-- 1. The audit table. Append-only by convention. Service-role only:
--    RLS is on with no policies, so the anon key can't read or write it.
CREATE TABLE IF NOT EXISTS order_events (
  id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  order_id    uuid        NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  -- order_placed | status_change | payment_change | delivery_change | refund_change
  event_type  text        NOT NULL,
  from_status text,
  to_status   text,
  -- consumer | farmer | rider | admin | system
  actor_type  text        NOT NULL DEFAULT 'system',
  actor_id    uuid,
  note        text,
  metadata    jsonb,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_order_events_order_id   ON order_events(order_id);
CREATE INDEX IF NOT EXISTS idx_order_events_created_at ON order_events(created_at);

ALTER TABLE order_events ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE order_events IS
  'Append-only audit trail of order changes. Written by the orders trigger; service-role only.';

-- 2. Trigger function. Reads the acting user from session GUCs that the
--    API routes set (app.actor_type / app.actor_id); falls back to 'system'.
CREATE OR REPLACE FUNCTION public.log_order_event()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_actor_type text;
  v_actor_id   uuid;
BEGIN
  v_actor_type := COALESCE(NULLIF(current_setting('app.actor_type', true), ''), 'system');
  BEGIN
    v_actor_id := NULLIF(current_setting('app.actor_id', true), '')::uuid;
  EXCEPTION WHEN others THEN
    v_actor_id := NULL;
  END;

  IF (TG_OP = 'INSERT') THEN
    INSERT INTO order_events (order_id, event_type, to_status, actor_type, actor_id, metadata)
    VALUES (
      NEW.id, 'order_placed', NEW.status,
      COALESCE(NULLIF(v_actor_type, 'system'), 'consumer'), v_actor_id,
      jsonb_build_object(
        'payment_method', NEW.payment_method,
        'delivery_type',  NEW.delivery_type,
        'total_price',    NEW.total_price
      )
    );
    RETURN NEW;
  END IF;

  -- UPDATE: emit one row per tracked field that actually changed.
  IF (NEW.status IS DISTINCT FROM OLD.status) THEN
    INSERT INTO order_events (order_id, event_type, from_status, to_status, actor_type, actor_id, note)
    VALUES (NEW.id, 'status_change', OLD.status, NEW.status, v_actor_type, v_actor_id,
            CASE WHEN NEW.status = 'declined' THEN NEW.decline_reason END);
  END IF;

  IF (NEW.payment_status IS DISTINCT FROM OLD.payment_status) THEN
    INSERT INTO order_events (order_id, event_type, from_status, to_status, actor_type, actor_id)
    VALUES (NEW.id, 'payment_change', OLD.payment_status, NEW.payment_status, v_actor_type, v_actor_id);
  END IF;

  IF (NEW.delivery_status IS DISTINCT FROM OLD.delivery_status) THEN
    INSERT INTO order_events (order_id, event_type, from_status, to_status, actor_type, actor_id)
    VALUES (NEW.id, 'delivery_change', OLD.delivery_status, NEW.delivery_status, v_actor_type, v_actor_id);
  END IF;

  IF (NEW.refund_status IS DISTINCT FROM OLD.refund_status) THEN
    INSERT INTO order_events (order_id, event_type, from_status, to_status, actor_type, actor_id, metadata)
    VALUES (NEW.id, 'refund_change', OLD.refund_status, NEW.refund_status, v_actor_type, v_actor_id,
            jsonb_build_object('refund_amount', NEW.refund_amount, 'refund_id', NEW.refund_id));
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_order_events_insert ON orders;
CREATE TRIGGER trg_order_events_insert
  AFTER INSERT ON orders
  FOR EACH ROW EXECUTE FUNCTION log_order_event();

DROP TRIGGER IF EXISTS trg_order_events_update ON orders;
CREATE TRIGGER trg_order_events_update
  AFTER UPDATE ON orders
  FOR EACH ROW EXECUTE FUNCTION log_order_event();

-- 3. One-time backfill for the 43 existing orders. Synthesizes an
--    approximate history from the timestamp columns we already store.
--    Guarded so re-running the migration won't duplicate events.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM order_events) THEN
    -- Order placed
    INSERT INTO order_events (order_id, event_type, to_status, actor_type, created_at)
    SELECT id, 'order_placed', status, 'system', created_at
    FROM orders;

    -- Final order status for anything past 'pending'
    INSERT INTO order_events (order_id, event_type, to_status, actor_type, note, created_at)
    SELECT id, 'status_change', status, 'system', decline_reason,
           COALESCE(refunded_at, delivered_at, created_at)
    FROM orders
    WHERE status IS DISTINCT FROM 'pending';

    -- Delivery milestones, from per-stage timestamps
    INSERT INTO order_events (order_id, event_type, to_status, actor_type, created_at)
    SELECT id, 'delivery_change', 'assigned', 'system', assigned_at
    FROM orders WHERE assigned_at IS NOT NULL;

    INSERT INTO order_events (order_id, event_type, to_status, actor_type, created_at)
    SELECT id, 'delivery_change', 'picked_up', 'system', picked_up_at
    FROM orders WHERE picked_up_at IS NOT NULL;

    INSERT INTO order_events (order_id, event_type, to_status, actor_type, created_at)
    SELECT id, 'delivery_change', 'out_for_delivery', 'system', out_for_delivery_at
    FROM orders WHERE out_for_delivery_at IS NOT NULL;

    INSERT INTO order_events (order_id, event_type, to_status, actor_type, created_at)
    SELECT id, 'delivery_change', 'delivered', 'system', delivered_at
    FROM orders WHERE delivered_at IS NOT NULL;

    -- Refunds
    INSERT INTO order_events (order_id, event_type, to_status, actor_type, metadata, created_at)
    SELECT id, 'refund_change', refund_status, 'system',
           jsonb_build_object('refund_amount', refund_amount, 'refund_id', refund_id),
           COALESCE(refunded_at, created_at)
    FROM orders WHERE refund_status IS NOT NULL;
  END IF;
END $$;

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { isModeratorRequest, getModeratorZone } from '@/lib/moderator-session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

function svc() {
  return createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )
}

const TYPES = ['delivery_delay', 'quality_complaint', 'payment_issue', 'other'] as const

// GET — every escalation in the moderator's zone, newest first, with the linked
// order's human code (e.g. "Order #YFF-1042") when there is one.
export async function GET(req: NextRequest) {
  if (!isModeratorRequest(req)) {
    return NextResponse.json({ error: 'Moderator login required.' }, { status: 401 })
  }
  const zone = getModeratorZone()
  const supabase = svc()

  const { data: rows, error } = await supabase
    .from('escalations')
    .select('id, order_id, type, description, raised_by, status, resolution_notes, resolved_at, created_at')
    .eq('region_slug', zone)
    .order('created_at', { ascending: false })
  if (error) {
    console.error('[YFF moderator/escalations] query failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }

  // Attach order codes for any escalations that reference an order.
  const orderIds = (rows ?? []).map((r) => r.order_id).filter(Boolean) as string[]
  const codeById = new Map<string, string>()
  if (orderIds.length > 0) {
    const { data: orders } = await supabase.from('orders').select('id, order_code').in('id', orderIds)
    for (const o of orders ?? []) codeById.set(o.id, o.order_code ?? '')
  }
  const escalations = (rows ?? []).map((r) => ({ ...r, order_code: r.order_id ? codeById.get(r.order_id) ?? null : null }))
  return NextResponse.json({ escalations })
}

// POST — log a complaint that came in by phone/WhatsApp. Optionally tie it to an
// order via its order_code (must be an order from a farmer in this zone).
export async function POST(req: NextRequest) {
  if (!isModeratorRequest(req)) {
    return NextResponse.json({ error: 'Moderator login required.' }, { status: 401 })
  }
  const zone = getModeratorZone()
  const supabase = svc()

  const body = await req.json().catch(() => null)
  if (!body) return NextResponse.json({ error: 'Invalid body.' }, { status: 400 })
  const b = body as Record<string, unknown>

  const typeRaw = String(b.type ?? 'other')
  const type = (TYPES as readonly string[]).includes(typeRaw) ? typeRaw : 'other'
  const description = String(b.description ?? '').trim()
  const raised_by = String(b.raised_by ?? '').trim() || null
  const orderCode = String(b.order_code ?? '').trim()
  if (!description) return NextResponse.json({ error: 'Describe the complaint.' }, { status: 400 })

  // Resolve an optional order_code to an order in this zone.
  let order_id: string | null = null
  if (orderCode) {
    const { data: order } = await supabase
      .from('orders')
      .select('id, farmer_id')
      .eq('order_code', orderCode)
      .maybeSingle()
    if (order?.farmer_id) {
      const { data: farmer } = await supabase
        .from('farmers').select('region_slug').eq('id', order.farmer_id).maybeSingle()
      if (farmer?.region_slug === zone) order_id = order.id
      else return NextResponse.json({ error: 'That order is not in your zone.' }, { status: 400 })
    } else {
      return NextResponse.json({ error: `No order found with code ${orderCode}.` }, { status: 400 })
    }
  }

  const { data: inserted, error } = await supabase
    .from('escalations')
    .insert({ region_slug: zone, type, description, raised_by, order_id, status: 'open' })
    .select('id')
    .single()
  if (error) {
    console.error('[YFF moderator/escalations] insert failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }
  return NextResponse.json({ id: inserted.id })
}

